import org.mockito.Spy;
import static org.junit.Assert.*;
import static org.junit.Assert.assertThrows;
import static org.mockito.Mockito.*;

public class StatisticalBarRenderer_drawItem_TriageGen0Test {

    @Spy
    private StatisticalBarRenderer renderer;

    private Graphics2D g2;
    private CategoryItemRendererState state;
    private Rectangle2D dataArea;
    private CategoryPlot plot;
    private CategoryAxis domainAxis;
    private ValueAxis rangeAxis;
    private StatisticalCategoryDataset statData;
    private CategoryDataset genericData;

    @Before
    public void setUp() {
        g2 = mock(Graphics2D.class);
        state = mock(CategoryItemRendererState.class);
        dataArea = new Rectangle2D.Double(0, 0, 100, 100);
        plot = mock(CategoryPlot.class);
        domainAxis = mock(CategoryAxis.class);
        rangeAxis = mock(ValueAxis.class);
        statData = mock(StatisticalCategoryDataset.class);
        genericData = mock(CategoryDataset.class);
    }

    @Test
    public void testDrawItemThrowsExceptionWhenDataIsNotStatistical() {
        assertThrows(IllegalArgumentException.class, () -> {
            renderer.drawItem(g2, state, dataArea, plot, domainAxis, rangeAxis, genericData, 0, 0, 0);
        });
    }

    @Test
    public void testDrawItemVerticalOrientation() {
        // Arrange
        when(plot.getOrientation()).thenReturn(PlotOrientation.VERTICAL);

        // Act
        renderer.drawItem(g2, state, dataArea, plot, domainAxis, rangeAxis, statData, 0, 0, 0);

        // Assert
        verify(renderer, times(1)).drawVerticalItem(
                eq(g2), eq(state), eq(dataArea), eq(plot), eq(domainAxis), eq(rangeAxis), eq(statData), eq(0), eq(0)
        );
        verify(renderer, never()).drawHorizontalItem(
                any(), any(), any(), any(), any(), any(), any(), anyInt(), anyInt()
        );
    }

    @Test
    public void testDrawItemHorizontalOrientation() {
        // Arrange
        when(plot.getOrientation()).thenReturn(PlotOrientation.HORIZONTAL);

        // Act
        renderer.drawItem(g2, state, dataArea, plot, domainAxis, rangeAxis, statData, 0, 0, 0);

        // Assert
        verify(renderer, times(1)).drawHorizontalItem(
                eq(g2), eq(state), eq(dataArea), eq(plot), eq(domainAxis), eq(rangeAxis), eq(statData), eq(0), eq(0)
        );
        verify(renderer, never()).drawVerticalItem(
                any(), any(), any(), any(), any(), any(), any(), anyInt(), anyInt()
        );
    }
}
